[URL Rewrite]
request if ${url} ~= /^https?:\/\/app02\.vgtime\.com:8080\/vgtime-app\/api\/v2\/init\/ad\.json$/i then reject_dict(200)
request if ${url} ~= /^(http:\/\/www\.vgtime\.com\/app\/topic\/\d+\.jhtml\?.*?&close_ad=)false(&page=\d&sign=\w+&timestamp=\d+&font_size=\d$)/i as urlMatch then redirect(302, "${urlMatch.1}true${urlMatch.2}")

[MITM]
hostname = %APPEND% app02.vgtime.com, www.vgtime.com
